quotes.text:
& .sync-details {
  display: flex;
  flex-direction: column;
  gap: var(--hub-sync-list-details-gap);
  flex-grow: 1;

  & .title {
    color: var(--color-text-base);
    text-transform: capitalize;
    margin-block: 0;
    font-size: 1rem;
  }

  & .subtitle {
    font-size: 0.9rem;
    color: var(--color-primary-default);

& .select-all {
  line-height: var(--hub-floating-button-line-height);
  align-self: end;
  margin-inline: 0;
  margin-block: 0 -20px;
  z-index: 1;
}
